import backtrader as bt


class TransactionCostSmaStrategy(bt.Strategy):
    params = (
        ("sma_period", 50),
        ("lot_size", 100),
        ("transaction_cost", 0.002),
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_period
        )
        self.order = None
        self.broker.setcommission(commission=self.p.transaction_cost)

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.sma[0]:
                self.order = self.buy(size=self.p.lot_size, exectype=bt.Order.Close)
        elif self.data.close[0] < self.sma[0]:
            self.order = self.close(exectype=bt.Order.Close)

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None
